<?php
require_once __DIR__.'/config/app.php';require_customer();$id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT o.*,p.id payment_id,p.proof_image,p.status actual_payment_status,b.bank_name,b.account_number,b.account_holder FROM orders o LEFT JOIN payments p ON p.order_id=o.id LEFT JOIN bank_accounts b ON b.id=p.bank_account_id WHERE o.id=? AND o.user_id=?');$stmt->execute([$id,current_user()['id']]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('Pesanan tidak ditemukan.');}$items=db()->prepare('SELECT oi.*,p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$items->execute([$id]);$items=$items->fetchAll();$history=db()->prepare('SELECT * FROM order_status_histories WHERE order_id=? ORDER BY created_at DESC,id DESC');$history->execute([$id]);$history=$history->fetchAll();$pageTitle='Detail Pesanan';require APP_ROOT.'/includes/header.php';
?>
<section class="page-hero"><div class="container"><div class="d-flex flex-wrap align-items-center gap-2"><div><div class="section-kicker">Detail pesanan</div><h1 class="mb-0"><?= e($order['order_number']) ?></h1></div><div class="ms-auto"><span class="badge text-bg-<?= status_class($order['order_status']) ?> fs-6"><?= order_status_label($order['order_status']) ?></span></div></div></div></section><section class="pb-5"><div class="container"><div class="row g-4"><div class="col-lg-8"><div class="content-card mb-4"><h5 class="fw-bold mb-3">Barang dipesan</h5><?php foreach($items as $item):?><div class="d-flex gap-3 align-items-center py-3 border-bottom"><img src="<?= e(product_image($item['image'])) ?>" class="rounded-3" style="width:64px;height:64px;object-fit:cover"><div class="flex-grow-1"><strong><?= e($item['product_name']) ?></strong><div class="small text-muted"><?= e($item['product_sku']) ?> • <?= $item['quantity'] ?> × <?= rupiah($item['unit_price']) ?></div></div><strong><?= rupiah($item['subtotal']) ?></strong></div><?php endforeach;?><div class="row justify-content-end mt-3"><div class="col-sm-6"><div class="d-flex justify-content-between mb-2"><span class="text-muted">Subtotal</span><span><?= rupiah($order['subtotal']) ?></span></div><div class="d-flex justify-content-between mb-2"><span class="text-muted">Ongkir</span><span><?= rupiah($order['shipping_cost']) ?></span></div><div class="d-flex justify-content-between fs-5 border-top pt-3"><strong>Total</strong><strong class="text-primary"><?= rupiah($order['total_amount']) ?></strong></div></div></div></div><div class="content-card"><h5 class="fw-bold mb-3">Informasi pemesanan</h5><div class="row g-3"><div class="col-md-6"><small class="text-muted d-block">Penerima</small><strong><?= e($order['recipient_name']) ?></strong><div><?= e($order['phone']) ?></div></div><div class="col-md-6"><small class="text-muted d-block">Alamat</small><div><?= e($order['full_address']) ?></div><div class="small text-muted mt-2">Jarak dari toko: <strong><?= number_format((float) $order['delivery_distance_km'], 2, ',', '.') ?> km</strong></div><a class="btn btn-sm btn-light-green mt-2" target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?= e($order['delivery_latitude'].',' . $order['delivery_longitude']) ?>"><i class="bi bi-geo-alt me-1"></i>Lihat titik pembeli</a></div><?php if($order['notes']):?><div class="col-12"><small class="text-muted d-block">Catatan</small><div><?= e($order['notes']) ?></div></div><?php endif;?></div></div></div><div class="col-lg-4"><div class="content-card mb-4"><h5 class="fw-bold">Pembayaran</h5><div class="d-flex justify-content-between my-3"><span>Metode</span><strong><?= $order['fulfillment_method']==='pickup'?'COD di Toko':($order['payment_method']==='cod'?'COD Antar':'Transfer Antar') ?></strong></div><div class="d-flex justify-content-between mb-3"><span>Status</span><span class="badge text-bg-<?= status_class($order['payment_status']) ?>"><?= payment_status_label($order['payment_status']) ?></span></div><?php if($order['payment_method']==='cod'):?><div class="alert alert-success small"><?= $order['fulfillment_method']==='pickup'?'Pesanan diambil dan dibayar langsung di toko.':'Pembayaran dilakukan saat barang diantar.' ?></div><?php else:?><div class="bg-light rounded-3 p-3 mb-3"><strong><?= e($order['bank_name']) ?></strong><div class="fs-5 fw-bold"><?= e($order['account_number']) ?></div><small class="text-muted">a.n. <?= e($order['account_holder']) ?></small><button class="btn btn-sm btn-light-green w-100 mt-2" data-copy="<?= e($order['account_number']) ?>"><i class="bi bi-copy"></i> Salin rekening</button></div><?php if($order['order_status']!=='cancelled'&&in_array($order['payment_status'],['unpaid','rejected'],true)):?><form action="<?= url('actions/payment-upload.php') ?>" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= $order['id'] ?>"><label class="form-label small fw-semibold">Bukti transfer (JPG/PNG/WebP, maks. 3 MB)</label><input class="form-control mb-2" type="file" name="proof_image" accept="image/jpeg,image/png,image/webp" required><button class="btn btn-primary w-100">Unggah Bukti</button></form><?php elseif($order['proof_image']):?><a class="btn btn-light-green w-100" target="_blank" href="<?= url('proof.php?order_id='.$order['id']) ?>"><i class="bi bi-image me-1"></i>Lihat Bukti</a><?php endif;?><?php endif;?><a class="btn btn-outline-success w-100 mt-2" href="<?= url('invoice.php?id='.$order['id']) ?>"><i class="bi bi-receipt me-1"></i>Lihat Nota</a><?php if($order['order_status']==='pending'&&in_array($order['payment_status'],['unpaid','rejected'],true)):?><form action="<?= url('actions/order-cancel.php') ?>" method="post" class="mt-2"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= $order['id'] ?>"><button class="btn btn-outline-danger w-100" data-confirm="Batalkan pesanan ini? Stok akan dikembalikan.">Batalkan Pesanan</button></form><?php endif;?></div><div class="content-card"><h5 class="fw-bold mb-4">Status pesanan</h5><div class="timeline"><?php foreach($history as $row):?><div class="timeline-item"><strong><?= order_status_label($row['new_status']) ?></strong><div class="small text-muted"><?= date('d M Y, H:i',strtotime($row['created_at'])) ?></div><?php if($row['notes']):?><div class="small"><?= e($row['notes']) ?></div><?php endif;?></div><?php endforeach;?></div></div></div></div></div></section>
<?php require APP_ROOT.'/includes/footer.php';?>
